&lt;ul type=&quot;disc&quot;&gt;
&lt;li style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif; color: rgb(58, 59, 65);&quot;&gt;&lt;span style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif; color: rgb(58, 59, 65);&quot;&gt;Competitive salary and stock option plan&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif; color: rgb(58, 59, 65);&quot;&gt;Medical, dental and vision insurance with employer paid options&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt; color: rgb(58, 59, 65);&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt; color: rgb(58, 59, 65);&quot;&gt;Competitive 401(k) program&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif; color: rgb(58, 59, 65);&quot;&gt;&lt;span style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif; color: rgb(58, 59, 65);&quot;&gt;Flexible PTO&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif; color: rgb(58, 59, 65);&quot;&gt;&lt;span style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif; color: rgb(58, 59, 65);&quot;&gt;Opportunities for professional growth and development&amp;nbsp;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif; color: rgb(58, 59, 65);&quot;&gt;&lt;span style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif; color: rgb(58, 59, 65);&quot;&gt;Paid parental leave&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif; color: rgb(58, 59, 65);&quot;&gt;&lt;span style=&quot;font-size: 10pt; font-family: helvetica, arial, sans-serif; color: rgb(58, 59, 65);&quot;&gt;Health &amp;amp; wellness initiatives&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
