&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt; color: rgb(58, 59, 65);&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt; color: rgb(58, 59, 65);&quot;&gt;Opportunities for professional growth and development&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt; color: rgb(58, 59, 65);&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt; color: rgb(58, 59, 65);&quot;&gt;Paid parental leave&lt;/span&gt;&lt;/li&gt;
